/**
 * Red-phase gate tests for track `ci_typecheck_alignment_20260603` / Phase 0.
 *
 * These tests are NOT unit tests of any application code. They are gate-level
 * regression guards that invoke the same `pnpm --filter science-advantage`
 * scripts that CI runs, and assert each gate exits 0.
 *
 * Phase 0 baseline (verified 2026-06-06, see
 * `measure/tracks/ci_typecheck_alignment_20260603/test-strategy.md` §0):
 *   - `pnpm --filter science-advantage check-types` exits non-zero with
 *     617 tsc errors (TS2339=347, TS2769=225, TS2741=12, TS2345=9, TS2322=7,
 *     TS2305=5, others=12). ~287 of the TS2339 cohort is jest-dom matcher
 *     narrowing suppressed by a multi-version vitest split (see §0).
 *   - `pnpm --filter science-advantage lint` exits non-zero with
 *     4 errors + 6 warnings. 4 are `react-hooks/immutability` in
 *     `components/features/teacher/analytics/student-lesson-detail-analytics.tsx`,
 *     6 are `@typescript-eslint/no-unused-vars` in
 *     `lib/gamification/badges.ts`.
 *   - `Role` from `@reading-advantage/auth` already includes `INTERN`
 *     (widened in `packages/auth/src/roles.ts`); coordination with Track 3
 *     (Argon2id + Auth Flatten) is intact.
 *
 * Both gate tests are expected to fail in the Red phase. The Track 3
 * coordination test is expected to pass and serves as a regression guard
 * for the canonical role source.
 */

import { spawnSync, type SpawnSyncReturns } from "node:child_process";
import { describe, it, expect } from "vitest";
import { ROLES, type Role } from "@reading-advantage/auth";

/**
 * Runs a pnpm command in the science-advantage package and returns the
 * captured result. We pin a 9-minute per-gate timeout because `tsc --noEmit`
 * on a 4k-line project takes several minutes; lint is usually <30s.
 *
 * Invokes `corepack pnpm` so the test works both in dev (where pnpm is
 * provisioned via corepack) and in CI (where pnpm is on PATH and corepack
 * forwards transparently).
 * @param args Arguments passed to `pnpm`.
 * @returns The captured spawn result.
 */
function runGate(args: readonly string[]): SpawnSyncReturns<string> {
  return spawnSync("corepack", ["pnpm", ...args], {
    cwd: process.cwd(),
    encoding: "utf8",
    stdio: ["ignore", "pipe", "pipe"],
    timeout: 540_000,
  });
}

const GATE_TIMEOUT_MS = 600_000;

describe("Phase 0 ci-gates (ci_typecheck_alignment_20260603)", () => {
  it(
    "check-types exits 0 (science-advantage type-clean)",
    { timeout: GATE_TIMEOUT_MS },
    () => {
      const result = runGate(["--filter", "science-advantage", "check-types"]);
      const output = `${result.stdout ?? ""}\n${result.stderr ?? ""}`;
      // Baseline expectation (Red phase): non-zero exit with 617 errors.
      // Track exit code, stdout, and stderr in the failure message so the
      // gate's failure mode is debuggable from the test report.
      expect(
        result.status,
        `pnpm --filter science-advantage check-types exited with code ${String(
          result.status,
        )}. Output:\n${output}`,
      ).toBe(0);
    },
  );

  it(
    "lint exits 0 (science-advantage lint-clean)",
    { timeout: GATE_TIMEOUT_MS },
    () => {
      const result = runGate(["--filter", "science-advantage", "lint"]);
      const output = `${result.stdout ?? ""}\n${result.stderr ?? ""}`;
      // Baseline expectation (Red phase): non-zero exit with 4 errors
      // and 6 warnings.
      expect(
        result.status,
        `pnpm --filter science-advantage lint exited with code ${String(
          result.status,
        )}. Output:\n${output}`,
      ).toBe(0);
    },
  );

  it(
    "Role type from @reading-advantage/auth includes INTERN (Track 3 coordination baseline)",
    () => {
      // This test guards the canonical role source that Track 3
      // (Argon2id + Auth Flatten) will preserve. If the `Role` union
      // ever narrows to drop INTERN, this test fails at type-check time
      // and we have lost the intern-role widening this track depends on.
      const role: Role = ROLES.INTERN;
      expect(role).toBe("INTERN");
      expect(ROLES.INTERN).toBe("INTERN");
    },
  );
});

/**
 * Red-phase gate tests for track `ci_typecheck_alignment_20260603` / Phase 1
 * ("Add `@testing-library/jest-dom/vitest` Types").
 *
 * Mirrors the Phase 0 file `lib/ci-gates/ci-gates.test.ts` in style: spawns the
 * same `tsc --noEmit` / file-read commands the implementer would run by hand
 * and asserts the post-Phase-1 end state.
 *
 * Per `measure/tracks/ci_typecheck_alignment_20260603/test-strategy.md` §0 and
 * §3, the **real** root cause of the matcher errors is the multi-version
 * vitest split (3.2.4 / 4.1.5 / 4.1.6) — not the missing jest-dom import.
 * The jest-dom/vitest import and the `@testing-library/jest-dom` dep are
 * already present in the source tree.
 *
 * The four tests in this file are:
 *
 *   1. `vitest.unit.setup.ts imports '@testing-library/jest-dom/vitest'`
 *      — **regression guard** (passes today). Locks the setup-file line so
 *      a future refactor that removes the import surfaces immediately.
 *   2. `package.json declares @testing-library/jest-dom in devDependencies`
 *      — **regression guard** (passes today). Locks the dep entry.
 *   3. `tsc --noEmit reports 0 TS errors for the jest-dom matcher cohort`
 *      — **red-phase assertion** (fails today, 287 / 345 errors). The
 *      end-state check: the vitest dedupe (Phase 5) plus the existing
 *      jest-dom import must drive this count to 0.
 *   4. `tsc --noEmit total error count drops below the Phase 0 baseline (617)`
 *      — **red-phase assertion** (fails today, ~617+ errors). The loose
 *      companion gate that catches a regression where the cohort is
 *      unchanged but other errors shift.
 */

import { readFileSync, existsSync } from "node:fs";
import { resolve } from "node:path";
import { spawnSync, type SpawnSyncReturns } from "node:child_process";
import { describe, it, expect } from "vitest";

const SCIENCE_ADVANTAGE_ROOT = process.cwd();

/**
 * The set of jest-dom matcher names whose TS errors are the
 * primary signal that the type augmentation is wired correctly. Sourced
 * from `@testing-library/jest-dom`'s public matcher list. Keep in sync
 * with `test-strategy.md` §0 / §3.
 */
const JEST_DOM_MATCHERS = [
  "toBeInTheDocument",
  "toHaveTextContent",
  "toHaveClass",
  "toBeVisible",
  "toBeDisabled",
  "toBeEmpty",
  "toBeEmptyDOMElement",
  "toHaveAttribute",
  "toHaveStyle",
  "toHaveFocus",
  "toBeChecked",
] as const;

/**
 * Runs `tsc --noEmit` inside the science-advantage package and returns the
 * captured result. We pin a 9-minute timeout because `tsc --noEmit` on the
 * science-advantage codebase takes several minutes.
 * @returns The captured spawn result.
 */
function runTscNoEmit(): SpawnSyncReturns<string> {
  return spawnSync("npx", ["tsc", "--noEmit"], {
    cwd: SCIENCE_ADVANTAGE_ROOT,
    encoding: "utf8",
    stdio: ["ignore", "pipe", "pipe"],
    timeout: 540_000,
  });
}

const TSC_TIMEOUT_MS = 600_000;

describe(
  "Phase 1 jest-dom types (ci_typecheck_alignment_20260603)",
  () => {
    describe("regression guards (currently pass; lock the install state)", () => {
      it("vitest.unit.setup.ts imports '@testing-library/jest-dom/vitest'", () => {
        const setupPath = resolve(
          SCIENCE_ADVANTAGE_ROOT,
          "vitest.unit.setup.ts",
        );
        expect(
          existsSync(setupPath),
          `Expected ${setupPath} to exist; the Phase 1.3 task requires this file to be present.`,
        ).toBe(true);
        const contents = readFileSync(setupPath, "utf8");
        expect(
          contents,
          `Expected ${setupPath} to contain \`import '@testing-library/jest-dom/vitest';\` so the @testing-library/jest-dom type augmentation is loaded before any test file uses the matchers. The current file content is:\n${contents}`,
        ).toMatch(/import\s+['"]@testing-library\/jest-dom\/vitest['"]/);
      });

      it("apps/science-advantage/package.json declares @testing-library/jest-dom in devDependencies", () => {
        const pkgPath = resolve(
          SCIENCE_ADVANTAGE_ROOT,
          "package.json",
        );
        const raw = readFileSync(pkgPath, "utf8");
        const pkg = JSON.parse(raw) as {
          devDependencies?: Record<string, string>;
        };
        const declared = pkg.devDependencies?.["@testing-library/jest-dom"];
        expect(
          declared,
          `Expected ${pkgPath} devDependencies['@testing-library/jest-dom'] to be declared so the type augmentation ships with the package. Found: ${JSON.stringify(declared)}`,
        ).toBeTruthy();
        // Spec says "Pin to a version compatible with @testing-library/react@^16.3.0"
        // — the installed version must satisfy the major-version range.
        expect(
          declared,
          `Expected @testing-library/jest-dom major to be ≥6 (compatible with @testing-library/react@^16.3.0). Found: ${declared}`,
        ).toMatch(/^\^?[6-9]\./);
      });
    });

    describe("red-phase assertions (currently fail; document the missing end-state)", () => {
      it(
        "tsc --noEmit reports 0 TS errors for the jest-dom matcher cohort",
        { timeout: TSC_TIMEOUT_MS },
        () => {
          const result = runTscNoEmit();
          const output = `${result.stdout ?? ""}\n${result.stderr ?? ""}`;
          const matcherPattern = new RegExp(
            `error TS\\d+: .*\\b(${JEST_DOM_MATCHERS.join("|")})\\b`,
            "g",
          );
          const cohortMatches = output.match(matcherPattern) ?? [];
          // Baseline (2026-06-06, see test-strategy.md §0): 287 TS2339 errors
          // in this cohort (345 in the broader matcher cohort incl. TS2769
          // overload errors). The Phase 1 end state is zero.
          expect(
            cohortMatches.length,
            `Expected zero tsc errors mentioning any jest-dom matcher in apps/science-advantage. ` +
              `Found ${cohortMatches.length}: first 3 are:\n` +
              cohortMatches
                .slice(0, 3)
                .map((m) => `  - ${m}`)
                .join("\n") +
              `\nFull tsc output (truncated to 4 KB):\n${output.slice(0, 4096)}`,
          ).toBe(0);
        },
      );

      it(
        "tsc --noEmit total error count drops below the Phase 0 baseline (617)",
        { timeout: TSC_TIMEOUT_MS },
        () => {
          const result = runTscNoEmit();
          const output = `${result.stdout ?? ""}\n${result.stderr ?? ""}`;
          const errorLines = output
            .split("\n")
            .filter((line) => /\berror TS\d+:/u.test(line));
          // Phase 1 alone is expected to drop the matcher cohort (~287 / ~345).
          // The test asserts the *total* count drops below the Phase 0
          // baseline (617). The companion `tscMatcherCohortIsZero` test
          // is the precise gate; this gate is the loose "did Phase 1 do
          // anything?" check that catches a regression where the cohort
          // is unchanged but other errors shift.
          const baseline = 617;
          expect(
            errorLines.length,
            `Expected tsc --noEmit total error count to drop below the Phase 0 baseline of ${String(baseline)} ` +
              `once the jest-dom matcher cohort (~287 / ~345) is gone. ` +
              `Found ${String(errorLines.length)} errors. ` +
              `First 3:\n` +
              errorLines
                .slice(0, 3)
                .map((l) => `  - ${l}`)
                .join("\n") +
              `\nFull tsc output (truncated to 4 KB):\n${output.slice(0, 4096)}`,
          ).toBeLessThan(baseline);
        },
      );
    });
  },
);

/**
 * Red-phase gate tests for track `ci_typecheck_alignment_20260603` / Phase 3
 * ("Add `lib/auth/{password,rate-limit}.test.ts` Siblings").
 *
 * Mirrors the Phase 0 / Phase 1 files in style: spawns the same `tsc --noEmit`
 * that CI runs and asserts the post-Phase-3 end state.
 *
 * Background (per `measure/tracks/ci_typecheck_alignment_20260603/spec.md`
 * FR-3 and `test-strategy.md` §1 row P3 / §3 cross-phase note):
 *
 *   - `apps/science-advantage/lib/auth/password.test.ts` does not yet exist.
 *     It is owned by Track 3 (Argon2id + Auth Flatten).
 *   - `apps/science-advantage/lib/auth/rate-limit.test.ts` already exists
 *     and currently imports from `./rate-limit`, but `lib/auth/rate-limit.ts`
 *     does not exist. The shared package has its own
 *     `packages/auth/src/rate-limit.ts`, but the app-local test imports
 *     the missing app-local sibling.
 *   - The spec offers two resolution paths: (a) create empty test files with
 *     `describe.skip(...)` placeholders, or (b) update `tsconfig.json` to
 *     exclude the (missing) test files. The test strategy recommends (b) —
 *     tsconfig exclude — because Track 3 and Track 10 are in flight and will
 *     replace these files soon; an empty stub creates merge friction.
 *
 * The end-state gate (per `test-strategy.md` §1 P3): `tsc` no longer reports
 * `Cannot find module './password'`. The companion end-state gate for
 * `./rate-limit` is added here because that is the *actual* error tsc reports
 * today.
 *
 * Tests in this file:
 *
 *   1. `tsc --noEmit reports 0 TS2307 errors for './rate-limit'`
 *      — **red-phase assertion** (fails today, 1 error in
 *      `lib/auth/rate-limit.test.ts:4`).
 *   2. `tsc --noEmit reports 0 TS2307 errors for './password'`
 *      — **regression guard** (passes today; locks the future state so
 *      Track 3 cannot silently regress by importing from a still-missing
 *      `./password` module).
 *   3. `tsc --noEmit total TS2307 error count for the lib/auth/* cohort is 0`
 *      — **red-phase assertion** (fails today, 1 error). Companion to tests
 *      1 + 2 that catches the case where the missing-module cohort is
 *      unchanged but other module errors shift.
 */

import { spawnSync, type SpawnSyncReturns } from "node:child_process";
import { describe, it, expect } from "vitest";

const SCIENCE_ADVANTAGE_ROOT = process.cwd();

/**
 * Runs `tsc --noEmit` inside the science-advantage package and returns the
 * captured result. We pin a 9-minute timeout because `tsc --noEmit` on the
 * science-advantage codebase takes several minutes.
 * @returns The captured spawn result.
 */
function runTscNoEmit(): SpawnSyncReturns<string> {
  return spawnSync("npx", ["tsc", "--noEmit"], {
    cwd: SCIENCE_ADVANTAGE_ROOT,
    encoding: "utf8",
    stdio: ["ignore", "pipe", "pipe"],
    timeout: 540_000,
  });
}

const TSC_TIMEOUT_MS = 600_000;

describe(
  "Phase 3 lib/auth/{password,rate-limit}.test.ts siblings (ci_typecheck_alignment_20260603)",
  () => {
    it(
      "tsc --noEmit reports 0 TS2307 errors for './rate-limit' (lib/auth/rate-limit.test.ts must resolve)",
      { timeout: TSC_TIMEOUT_MS },
      () => {
        const result = runTscNoEmit();
        const output = `${result.stdout ?? ""}\n${result.stderr ?? ""}`;
        // Match TS2307 "Cannot find module './rate-limit'" lines only.
        // The match is path-anchored on the module specifier so we don't
        // accidentally swallow `lib/auth/rate-limit.test.ts` (the importer)
        // or `packages/auth/src/rate-limit` (a different module that is
        // correctly resolvable).
        const rateLimitMissing = output
          .split("\n")
          .filter(
            (line) =>
              /error TS2307:/u.test(line) &&
              /['"]\.\/rate-limit['"]/u.test(line),
          );
        expect(
          rateLimitMissing.length,
          `Expected zero tsc TS2307 errors for the missing module './rate-limit'. ` +
            `Found ${String(rateLimitMissing.length)}: \n` +
            rateLimitMissing.map((l) => `  - ${l}`).join("\n") +
            `\nPer test-strategy.md §1 P3, the recommended fix is option (b): ` +
            `add 'lib/auth/rate-limit.test.ts' to tsconfig.json 'exclude' ` +
            `(Track 10 will own the real rate-limit module). ` +
            `Alternatively, create lib/auth/rate-limit.ts with a ` +
            `'LoginRateLimiter' export, or change the test's import to ` +
            `point at the shared '@reading-advantage/auth' module. ` +
            `\nFull tsc output (truncated to 4 KB):\n${output.slice(0, 4096)}`,
        ).toBe(0);
      },
    );

    it(
      "tsc --noEmit reports 0 TS2307 errors for './password' (lib/auth/password.test.ts must resolve)",
      { timeout: TSC_TIMEOUT_MS },
      () => {
        const result = runTscNoEmit();
        const output = `${result.stdout ?? ""}\n${result.stderr ?? ""}`;
        // The './password' module is owned by Track 3 (Argon2id). Today
        // `lib/auth/password.test.ts` does not exist, so the import does
        // not even reach tsc — this test passes today and acts as a
        // regression guard so a future Track-3 merge that imports a
        // still-missing './password' module surfaces immediately.
        const passwordMissing = output
          .split("\n")
          .filter(
            (line) =>
              /error TS2307:/u.test(line) &&
              /['"]\.\/password['"]/u.test(line),
          );
        expect(
          passwordMissing.length,
          `Expected zero tsc TS2307 errors for the missing module './password'. ` +
            `Found ${String(passwordMissing.length)}: \n` +
            passwordMissing.map((l) => `  - ${l}`).join("\n") +
            `\nIf Track 3 (Argon2id) has not yet shipped lib/auth/password.ts, ` +
            `the recommended interim fix is option (b) tsconfig exclude per ` +
            `test-strategy.md §1 P3 — add 'lib/auth/password.test.ts' to ` +
            `tsconfig.json 'exclude' until the real module lands. ` +
            `\nFull tsc output (truncated to 4 KB):\n${output.slice(0, 4096)}`,
        ).toBe(0);
      },
    );

    it(
      "tsc --noEmit reports 0 TS2307 errors for the lib/auth/* missing-module cohort",
      { timeout: TSC_TIMEOUT_MS },
      () => {
        const result = runTscNoEmit();
        const output = `${result.stdout ?? ""}\n${result.stderr ?? ""}`;
        // Cohort gate: any TS2307 inside the lib/auth/* import graph.
        // This is the loose companion to tests 1 + 2 — catches the case
        // where the cohort is unchanged but the specific module names
        // shift (e.g. someone renames './rate-limit' to
        // '../rate-limit/rate-limit' before Track 10 lands).
        const cohort = output
          .split("\n")
          .filter(
            (line) =>
              /error TS2307:/u.test(line) &&
              /lib\/auth\//u.test(line) &&
              /['"]\.\//u.test(line),
          );
        expect(
          cohort.length,
          `Expected zero tsc TS2307 errors for missing relative modules in ` +
            `the lib/auth/* import graph. Found ${String(cohort.length)}: \n` +
            cohort.map((l) => `  - ${l}`).join("\n") +
            `\nFull tsc output (truncated to 4 KB):\n${output.slice(0, 4096)}`,
        ).toBe(0);
      },
    );
  },
);

/**
 * Red-phase gate tests for track `ci_typecheck_alignment_20260603` / Phase 6
 * ("Misc Cleanup").
 *
 * Mirrors the Phase 1 / Phase 3 / Phase 4 files in style: spawns the same
 * `tsc --noEmit` that CI runs, caches the output once via `beforeAll`, and
 * asserts the post-Phase-6 end state across all 4 files in the cohort.
 *
 * Background (per `measure/tracks/ci_typecheck_alignment_20260603/spec.md`
 * FR-6 and `test-strategy.md` §1 row P6 / §5 P6 notes):
 *
 *   - `components/features/auth/user-menu.tsx:89,54` — TS2322
 *     (`string | null` is not assignable to `string | undefined`). The
 *     `<AvatarImage alt={user.name} />` prop receives `user.name` which
 *     is `string | null` on the session-user shape, but Radix's
 *     `AvatarImage` `alt` is `string | undefined`. Fix: coerce with
 *     `alt={user.name ?? ''}` or `alt={user.name ?? undefined}` (the
 *     existing `src={user.image || undefined}` pattern at line 89 is
 *     the closest precedent — apply the same `|| undefined` shape).
 *   - `components/features/lesson/__tests__/review-block.test.tsx:13,1` —
 *     TS2304 (`Cannot find name 'beforeEach'`). Line 3 imports
 *     `afterEach, describe, expect, it, vi` from `'vitest'` and omits
 *     `beforeEach`. Fix: add `beforeEach` to the named-imports list.
 *   - `lib/gamification/xp.test.ts:124,31` — TS2367 (`This comparison
 *     appears to be unintentional because the types '2' and '1' have no
 *     overlap`). Line 121 declares `const attemptNumber = 2;` which
 *     narrows the literal type to `2`; line 124 then writes
 *     `attemptNumber === 1` which tsc rejects as an impossible
 *     comparison (the test *intends* to verify the `=== 1` branch's
 *     `false` path, but the literal narrowing makes the check
 *     statically known). Fix: widen the type by annotating
 *     `const attemptNumber: number = 2;` (or extract the bonus
 *     calculation into a tested helper so the literal narrowing does
 *     not collapse the branch — the helper approach is the more
 *     architecturally honest fix because the inline calculation today
 *     duplicates production logic and is therefore not actually
 *     exercising the function under test).
 *   - `app/api/students/[studentId]/mastery-profile/route.integration.test.ts`
 *     lines 66, 85, 219, 228, 236 — 5 TS2769 errors (`No overload
 *     matches this call`). The Drizzle `.insert(scienceStandards).values({...})`,
 *     `.insert(scienceLessons).values({...})`, and
 *     `.insert(scienceAttempts).values({...})` calls have argument
 *     shapes that no longer match the schema — likely a stale
 *     `framework: 'THAI'` literal that no longer matches the enum, or a
 *     missing required field after a recent schema widening. Fix:
 *     reconcile the seed-helper `.values({...})` payloads against the
 *     current Drizzle schemas in `packages/db/src/schema/science.ts`.
 *     The 5 errors are tightly coupled — fixing one likely fixes all
 *     five (same root cause).
 *
 * The end-state gate (per `test-strategy.md` §1 P6): `tsc` reports 0
 * errors in each of the 4 named files. The plan's "4 errors" undercount
 * is documented in the §6 plan status note; the actual cohort is 8
 * errors across 4 files. The cohort gate (test 6) and the post-Phase-5
 * baseline gate (test 7) catch the case where one of the 4 files
 * regresses with a new error of a different type.
 *
 * Performance note: `tsc --noEmit` on the science-advantage codebase
 * takes ~30s. To keep the test file under the supervisor role-timeout
 * budget, we run tsc once via `beforeAll` and cache the output, then
 * run all 7 assertions against the cached string. This is the same
 * pattern used in `phase-4-process-env-cast.test.ts`.
 *
 * Tests in this file:
 *
 *   1. `tsc --noEmit completed (sanity check on shared setup)`
 *      — passes as long as tsc exits; guards against silent
 *      "everything looks clean" failures when tsc was killed by a
 *      timeout.
 *   2. `tsc --noEmit reports 0 errors in components/features/auth/user-menu.tsx`
 *      — **red-phase assertion** (fails today, 1 TS2322 error at line 89).
 *   3. `tsc --noEmit reports 0 errors in components/features/lesson/__tests__/review-block.test.tsx`
 *      — **red-phase assertion** (fails today, 1 TS2304 error at line 13).
 *   4. `tsc --noEmit reports 0 errors in lib/gamification/xp.test.ts`
 *      — **red-phase assertion** (fails today, 1 TS2367 error at line 124).
 *   5. `tsc --noEmit reports 0 errors in app/api/students/[studentId]/mastery-profile/route.integration.test.ts`
 *      — **red-phase assertion** (fails today, 5 TS2769 errors at
 *      lines 66, 85, 219, 228, 236).
 *   6. `tsc --noEmit total error count for the Phase 6 cohort is 0`
 *      — **red-phase assertion** (fails today, 8 errors). The loose
 *      companion to tests 2–5 that catches the case where one of the 4
 *      files regresses with a new error of a different type.
 *   7. `tsc --noEmit total error count drops below the post-Phase-5 baseline (273)`
 *      — **red-phase assertion** (fails today, 273 errors baseline).
 *      The end-state total is ≤ 265 (273 - 8). Asserting `< 273` is
 *      the loose gate; asserting `=== 265` would be brittle (other
 *      phases may shift the count before this one runs).
 */

import { spawnSync, type SpawnSyncReturns } from "node:child_process";
import { beforeAll, describe, it, expect } from "vitest";

const SCIENCE_ADVANTAGE_ROOT = process.cwd();

/**
 * The set of files owned by Phase 6. Each gets a per-file zero-error
 * assertion plus participation in the cohort gate (test 6).
 */
const PHASE_6_FILES = [
  "components/features/auth/user-menu.tsx",
  "components/features/lesson/__tests__/review-block.test.tsx",
  "lib/gamification/xp.test.ts",
  "app/api/students/[studentId]/mastery-profile/route.integration.test.ts",
] as const;

/**
 * Post-Phase-5 baseline (verified 2026-06-07): 273 tsc errors. Phase 6
 * alone is expected to drop the 8-error misc cohort (4 files × 1+1+1+5
 * errors). The companion `cohortIsZero` test is the precise gate; this
 * gate is the loose "did Phase 6 do anything?" check.
 */
const POST_PHASE_5_BASELINE = 273;

/**
